def monotonic(l: list) -> bool:
    """
    Return True if the list elements are monotonic, that is, entirely non-increasing or non-decreasing.
    Sequences with equal adjacent elements are considered monotonic.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if len(l) < 2:
        return True
    non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
    non_increasing = all(x >= y for x, y in zip(l, l[1:]))
    return non_decreasing or non_increasing



