def prime_length(string):
    """
    Return True if the length of the input string is a prime number, and False otherwise.

    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.

    Examples:
    prime_length('Hello') == True     # length 5, which is prime
    prime_length('abcdcba') == True   # length 7, which is prime
    prime_length('kittens') == True   # length 7, which is prime
    prime_length('orange') == False   # length 6, which is not prime
    """
    n = len(string)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(n ** 0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True



