def digits(n):
    """
    Given a positive integer n, return the product of its odd digits.
    If n contains no odd digits, return 0.
    If n contains exactly one odd digit, return that digit.

    For example:
    digits(1) == 1
    digits(4) == 0
    digits(235) == 15
    digits(3) == 3
    digits(2468) == 0
    """
    odd_digits = [int(d) for d in str(n) if int(d) % 2 == 1]
    if not odd_digits:
        return 0
    product = 1
    for d in odd_digits:
        product *= d
    return product



