from typing import List

def parse_nested_parens(paren_string: str) -> str:
    """
    Given a string containing multiple groups of nested parentheses separated by spaces, 
    return a string representing the maximum nesting depth of parentheses for each group,
    with the depths separated by commas and spaces.

    For each group (a substring consisting of a balanced parentheses expression), the maximum nesting depth
    is defined as the highest number of open parentheses that are nested inside each other at any point.
    For example:
      - "(()())" has a maximum nesting depth of 2,
      - "((()))" has a maximum nesting depth of 3,
      - "()" has a maximum nesting depth of 1.

    The function returns the depths as integers converted to strings, joined by ", ".

    Restrictions:
    - The calculation of the maximum nesting depth for each group must not use explicit loops (for/while) or recursion.
    - It is permitted to use built-in higher-order functions (e.g., map, reduce), comprehensions, generator expressions, or other implicit iteration constructs.
    - The input groups are assumed to be balanced parentheses expressions.
    - The phrase about working for real numbers is irrelevant; the nesting depth is always an integer.

    Example:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    '2, 3, 1, 3'
    """
    def max_depth(group: str) -> str:
        # Use reduce to track current depth and max depth
        # accumulator: (current_depth, max_depth)
        def reducer(acc, ch):
            current, maximum = acc
            current = current + 1 if ch == '(' else current - 1
            maximum = max(maximum, current)
            return (current, maximum)
        _, depth = reduce(reducer, group, (0, 0))
        return str(depth)

    return ", ".join(map(max_depth, paren_string.split()))



