from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    notes = music_string.split(' ')
    # Fixed mapping of note to beats
    beat_map = {'o': 4, 'o|': 2, '.|': 1}

    # Unpack exactly 11 notes without loops
    n0, n1, n2, n3, n4, n5, n6, n7, n8, n9, n10 = notes

    beats = [
        beat_map[n0], beat_map[n1], beat_map[n2], beat_map[n3], beat_map[n4],
        beat_map[n5], beat_map[n6], beat_map[n7], beat_map[n8], beat_map[n9], beat_map[n10]
    ]

    # Count occurrences without loops or recursion
    c_o = (n0 == 'o') + (n1 == 'o') + (n2 == 'o') + (n3 == 'o') + (n4 == 'o') + (n5 == 'o') + (n6 == 'o') + (n7 == 'o') + (n8 == 'o') + (n9 == 'o') + (n10 == 'o')
    c_o_bar = (n0 == 'o|') + (n1 == 'o|') + (n2 == 'o|') + (n3 == 'o|') + (n4 == 'o|') + (n5 == 'o|') + (n6 == 'o|') + (n7 == 'o|') + (n8 == 'o|') + (n9 == 'o|') + (n10 == 'o|')
    c_dot_bar = (n0 == '.|') + (n1 == '.|') + (n2 == '.|') + (n3 == '.|') + (n4 == '.|') + (n5 == '.|') + (n6 == '.|') + (n7 == '.|') + (n8 == '.|') + (n9 == '.|') + (n10 == '.|')

    # Determine max frequency
    max_freq = c_o
    # Initialize most common note to 'o'
    most_common_note = 'o'

    # Compare with 'o|'
    if c_o_bar > max_freq or (c_o_bar == max_freq and beat_map['o|'] > beat_map[most_common_note]):
        max_freq = c_o_bar
        most_common_note = 'o|'

    # Compare with '.|'
    if c_dot_bar > max_freq or (c_dot_bar == max_freq and beat_map['.|'] > beat_map[most_common_note]):
        most_common_note = '.|'

    return beats, most_common_note



