def decode_shift(s: str):
    """
    Takes as input a string encoded with the encode_shift function and returns the decoded string.

    The encoding works as follows:
    - If the input string consists only of numeric characters ('0'-'9'), encode_shift returns the reversed string.
      In this case, decode_shift reverses the string back to the original numeric string.
    - Otherwise, encode_shift shifts every lowercase alphabetic character ('a'-'z') forward by 5 positions,
      wrapping around within 'a' to 'z'. For example, 'a' becomes 'f', 'z' becomes 'e'.
    - decode_shift reverses this shift by moving every lowercase alphabetic character backward by 5 positions,
      wrapping within 'a' to 'z'.
    - Non-alphabetic and non-numeric characters are also shifted using the same modular arithmetic within 'a'-'z'
      without preserving their original type or range (i.e., their Unicode code points are treated as if they were lowercase letters).
      This means the decoded output may differ from the original for such characters.

    Parameters:
        s (str): The encoded string produced by encode_shift.

    Returns:
        str: The decoded original string.

    Examples:
        decode_shift("fgh") == "abc"           # letters shifted back by 5
        decode_shift("321") == "123"           # numeric string reversed back
        decode_shift("%E&") == " @!"           # shifted non-alphabetic characters decoded
    """
    if s.isdigit():
        return s[::-1]
    res = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # shift backward by 5 with wrap
            offset = (ord(ch) - ord('a') - 5) % 26
            res.append(chr(offset + ord('a')))
        else:
            # shift Unicode code point backward by 5 without wrap
            res.append(chr(ord(ch) - 5))
    return ''.join(res)



