def smallest_change(arr):
    words = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
             "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
             "seventeen", "eighteen", "nineteen", "twenty"]
    n = len(arr)
    if n <= 1:
        return "zero"
    # Compute mismatches without loops or recursion by using zip on arr and reversed arr,
    # slicing only first half pairs: arr[:n//2] and arr[-1:-(n//2+1):-1]
    left = arr[:n//2]
    right = arr[-1:-(n//2+1):-1]
    # Count mismatches using sum of booleans via map and zip
    mismatches = sum(map(lambda x: x[0] != x[1], zip(left, right)))
    return words[mismatches]



