def total_match(lst1, lst2):
    if not lst1 and not lst2:
        return []
    if not lst1:
        return lst2
    if not lst2:
        return lst1

    lst1_has_str = any(isinstance(x, str) for x in lst1)
    lst2_has_str = any(isinstance(x, str) for x in lst2)

    if lst1_has_str or lst2_has_str:
        # Find longest string in lst1
        max_len1 = max(len(x) if isinstance(x, str) else 0 for x in lst1)
        max_len2 = max(len(x) if isinstance(x, str) else 0 for x in lst2)
        if max_len1 >= max_len2:
            return ' '.join(str(x) for x in lst1)
        else:
            return ' '.join(str(x) for x in lst2)

    # Both lists contain only integers
    def digit_count(n):
        return len(str(abs(n)))
    total_digits_1 = sum(digit_count(x) for x in lst1)
    total_digits_2 = sum(digit_count(x) for x in lst2)

    if total_digits_1 <= total_digits_2:
        return ' '.join(str(x) for x in lst1)
    else:
        return ' '.join(str(x) for x in lst2)



