def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    sorted_arr = sorted(arr)
    def check_shift(k):
        # right shift by k: arr[(i - k) % n]
        shifted = arr[-k:] + arr[:-k]
        return shifted == sorted_arr
    # try all shifts from 0 to n-1 using recursion
    def try_shifts(k):
        if k == n:
            return False
        if check_shift(k):
            return k
        return try_shifts(k+1)
    return try_shifts(0)



