    d0 = int(n[0]) if len(n) > 0 else 0
    d1 = int(n[1]) if len(n) > 1 else 0
    d2 = int(n[2]) if len(n) > 2 else 0
    d3 = int(n[3]) if len(n) > 3 else 0
    d4 = int(n[4]) if len(n) > 4 else 0
    d5 = int(n[5]) if len(n) > 5 else 0
    d6 = int(n[6]) if len(n) > 6 else 0
    d7 = int(n[7]) if len(n) > 7 else 0
    d8 = int(n[8]) if len(n) > 8 else 0
    d9 = int(n[9]) if len(n) > 9 else 0

    p0 = d0 if d0 % 2 == 1 else 1
    p1 = d1 if d1 % 2 == 1 else 1
    p2 = d2 if d2 % 2 == 1 else 1
    p3 = d3 if d3 % 2 == 1 else 1
