def sum_squares(lst):
    # Helper to safely get element or 0 if index out of range
    def get(i):
        return lst[i] if i < len(lst) else 0

    # Process indices 0 to 5 as per rules:
    # idx multiple of 3 -> square
    # idx multiple of 2 but not 3 -> cube
    # else unchanged
    v0 = get(0)
    v1 = get(1)
    v2 = get(2)
    v3 = get(3)
