from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split(' ')
    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        balanced = True
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
                if current_depth < 0:
                    balanced = False
                    break
            else:
                # According to spec, only '(' and ')' expected, but no other chars.
                # So this branch theoretically unreachable.
                balanced = False
                break
        if current_depth != 0:
            balanced = False
        results.append(max_depth if balanced else 0)
    return results



