def max_fill(layout, limit):
    total_lowerings = 0
    for row in layout:
        n = len(row)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + row[i]

        # dp[i] = minimal lowerings to clear row[:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for end in range(1, n + 1):
            for start in range(end):
                ones_in_segment = prefix[end] - prefix[start]
                if ones_in_segment <= limit:
                    dp[end] = min(dp[end], dp[start] + (1 if ones_in_segment > 0 else 0))

        total_lowerings += dp[n]
    return total_lowerings



