def order_by_points(items):
    def digit_sum(n):
        s = str(n)
        if n >= 0:
            return sum(int(d) for d in s)
        else:
            # Negative number: negate only first digit after minus
            digits = s[1:]
            if not digits:
                return 0
            first = -int(digits[0])
            rest = sum(int(d) for d in digits[1:])
            return first + rest
    return sorted(items, key=digit_sum)



