def prime_length(string):
    """
    Return True if and only if the length of the input string is a prime number; otherwise, return False.

    The function returns False for strings of length zero or one since these lengths are not prime.

    Examples:
    prime_length('Hello') == True       # length 5 is prime
    prime_length('abcdcba') == True     # length 7 is prime
    prime_length('kittens') == True     # length 7 is prime
    prime_length('orange') == False     # length 6 is not prime
    prime_length('') == False            # length 0 is not prime
    prime_length('a') == False           # length 1 is not prime
    """
    n = len(string)
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return False
    return True



