def sum_squares(lst):
    """
    Given a list of integers `lst`, this function returns the sum of all elements after transforming certain entries based on their indices as follows:

    - If an element's index is a multiple of 3, the element is squared.
    - Otherwise, if an element's index is a multiple of 4 (but not a multiple of 3), the element is cubed.
    - All other elements remain unchanged.

    Note: For indices that are multiples of both 3 and 4, the squaring operation (multiple of 3 rule) takes priority.

    Examples:
    For lst = [1, 2, 3], the output should be 6
    For lst = [], the output should be 0
    For lst = [-1, -5, 2, -1, -5], the output should be -126
    """
    total = 0
    for i, v in enumerate(lst):
        if i % 3 == 0:
            total += v * v
        elif i % 4 == 0:
            total += v * v * v
        else:
            total += v
    return total



