from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Given a string consisting of multiple groups of nested parentheses separated by spaces, 
    return a list of integers where each integer corresponds to the maximum depth of nested 
    parentheses within each group.

    Each group is defined explicitly by spaces in the input string; the function does not infer 
    group boundaries from balanced substrings if no spaces are present.

    For example:
    - '(() ())' contains two groups: '(()' and '())', with maximum depths 2 and 1 respectively.
    - '((()))' is a single group with maximum depth 3.

    Examples:
    >>> parse_nested_parens('(()()) ((())) () ((())()())')
    [2, 3, 1, 3]

    >>> parse_nested_parens('(()())((()))()((())()())')
    [2, 3, 1, 3]

    The input string may contain multiple groups separated by spaces, and each group consists only of '(' and ')' characters.
    The function computes the maximum nesting depth for each group independently.
    """
    if paren_string == '':
        return []
    groups = paren_string.split(' ')
    depths = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                if current_depth > 0:
                    current_depth -= 1
                # unmatched ')' do not affect max_depth or current_depth below zero
        depths.append(max_depth)
    return depths



