def monotonic(l: list):
    """
    Return True if the list elements are monotonic, meaning the sequence is entirely nondecreasing or entirely nonincreasing.
    Nondecreasing sequences are those where each element is greater than or equal to the previous element.
    Nonincreasing sequences are those where each element is less than or equal to the previous element.
    Sequences with equal adjacent elements are considered monotonic.
    The input list is assumed to contain elements that are mutually comparable using standard comparison operators.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    >>> monotonic([1, 2, 2, 3])
    True
    """
    if len(l) < 2:
        return True

    nondecreasing = True
    nonincreasing = True

    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            nondecreasing = False
        if l[i] > l[i - 1]:
            nonincreasing = False

        if not nondecreasing and not nonincreasing:
            return False

    return True



