def circular_shift(x: int, shift: int) -> str:
    s = str(x)
    n = len(s)
    if n == 1 or shift == 0:
        return s
    shift %= n
    if shift == 0:
        return s
    # Positive shift: rotate right by shift
    # Negative shift: rotate left by abs(shift)
    if shift > 0:
        return s[-shift:] + s[:-shift]
    else:
        shift = -shift
        return s[shift:] + s[:shift]



