def max_fill(grid, capacity):
    """
    Given a rectangular grid of wells, where each row represents a single well and each element in the row is either 0 or 1 indicating a single unit of water, compute the total number of buckets needed to extract all the water from all wells.

    Each bucket has the same capacity. For each well, count the total units of water (i.e., the number of 1s in the row), divide this count by the bucket capacity, round up to the nearest whole number to determine how many buckets are needed for that well, and then sum these counts across all wells.

    Parameters:
    - grid: List[List[int]] — a list of lists representing the wells, where each inner list contains 0s and 1s.
    - capacity: int — the capacity of each bucket.

    Returns:
    - int — the total number of buckets needed to extract all the water from all wells.

    Example:
    max_fill([[1, 0, 1], [1, 1, 1]], 2) == 3
    Explanation:
    - First well has 2 units of water → 2 / 2 = 1 bucket
    - Second well has 3 units of water → 3 / 2 = 1.5 → 2 buckets
    Total buckets = 1 + 2 = 3
    """
    from math import ceil
    return sum(ceil(sum(row) / capacity) for row in grid if sum(row) > 0)



