def triples_sum_to_zero(l: list):
    n = len(l)
    if n < 3:
        return False
    l_sorted = sorted((val, idx) for idx, val in enumerate(l))
    for i in range(n - 2):
        a_val, a_idx = l_sorted[i]
        left, right = i + 1, n - 1
        while left < right:
            b_val, b_idx = l_sorted[left]
            c_val, c_idx = l_sorted[right]
            s = a_val + b_val + c_val
            if s == 0:
                if len({a_idx, b_idx, c_idx}) == 3:
                    return True
                # Even if values sum to zero, indices must be distinct
                # Move pointers to find other pairs
                # Since values can repeat, try to move both pointers to find different indices
                # Try moving left pointer
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False



