def maximum(arr, k):
    if k == 0:
        return []
    sorted_desc = sorted(arr, reverse=True)
    kth_largest = sorted_desc[k-1]
    # Include all elements strictly greater than kth largest
    greater_vals = {v for v in arr if v > kth_largest}
    result = [v for v in arr if v in greater_vals]

    # How many elements included so far
    count_so_far = len(result)
    # Number of kth largest elements needed to reach k
    needed = k - count_so_far
    # Include needed kth largest elements by original order
    kth_elements = [v for v in arr if v == kth_largest]
    result.extend(kth_elements[:needed])

    return sorted(result)



