def anti_shuffle(s):
    """
    Takes a string `s` and returns a new string where each word is replaced by a version of itself 
    with its characters sorted in ascending order according to their ASCII values. 

    Words are defined as sequences of non-space characters separated by whitespace. Punctuation 
    attached to words is treated as part of the word and included in the sorting. 

    The output string contains the transformed words joined by single spaces, normalizing all original 
    spacing (e.g., multiple spaces, tabs, newlines) to a single space between words.
    """
    words = s.split()
    sorted_words = [''.join(sorted(word)) for word in words]
    return ' '.join(sorted_words)



