def select_words(s: str, n: int):
    import string
    vowels = {'a', 'e', 'i', 'o', 'u'}
    punctuation = set(string.punctuation)
    result = []
    for word in s.split():
        # Strip all punctuation characters from the word (anywhere, not just ends)
        stripped = ''.join(ch for ch in word if ch not in punctuation)
        # Count consonants: alphabetic letters not vowels, case-insensitive
        consonant_count = sum(
            1 for ch in stripped.lower() if ch.isalpha() and ch not in vowels
        )
        if consonant_count == n:
            result.append(stripped)
    return result



