def maximum(arr, k):
    from collections import Counter
    sorted_arr_desc = sorted(arr, reverse=True)
    kth_val = sorted_arr_desc[k-1]
    count_kth_val_in_arr = arr.count(kth_val)
    count_strictly_greater = sum(1 for x in sorted_arr_desc if x > kth_val)
    needed_kth_val = k - count_strictly_greater
    c_result = Counter()
    result = []
    for x in sorted_arr_desc:
        if x > kth_val:
            result.append(x)
            c_result[x] += 1
        elif x == kth_val and c_result[x] < needed_kth_val:
            result.append(x)
            c_result[x] += 1
        if len(result) == k:
            break
    return sorted(result)



