def parse_music(music: str) -> list[int]:
    symbols = []
    i = 0
    n = len(music)
    while i < n:
        c = music[i]
        if c == 'o':
            # Check if next char is '|'
            if i + 1 < n and music[i + 1] == '|':
                symbols.append('o|')
                i += 2
            else:
                symbols.append('o')
                i += 1
        elif c == '.':
            # next char must be '|'
            if i + 1 < n and music[i + 1] == '|':
                symbols.append('.|')
                i += 2
            else:
                # No other valid symbol starting with '.' alone, but spec doesn't restrict input
                # Just treat '.' alone as invalid symbol? Spec doesn't say. Skip or error?
                # To preserve domain, skip just '.' if no '|'
                i += 1
        elif c in ' \t\n\r':
            i += 1  # skip whitespace
        else:
            # Unknown characters ignored or skipped, spec doesn't forbid
            i += 1

    mapping = {'o': 4, 'o|': 2, '.|': 1}
    return [mapping[s] for s in symbols]



