def filter_integers(iterable):
    """
    Given an iterable, return a list containing only those elements whose type is exactly int.
    The returned list preserves the original order of such elements and includes duplicates exactly as they appear.
    Elements of subclasses of int (e.g., bool) are excluded.

    Examples:
