def select_words(s: str, n: int):
    if not s:
        return []
    vowels = set('aeiouAEIOU')
    result = []
    words = s.split()
    for w in words:
        length = len(w)
        # Precompute prefix sums of non-vowel counts for efficiency
        prefix_nv = [0] * (length + 1)
        for i, c in enumerate(w, 1):
            prefix_nv[i] = prefix_nv[i - 1] + (0 if c in vowels else 1)
        # Try all substrings in w
        for start in range(length):
            for end in range(start + 1, length + 1):
                if prefix_nv[end] - prefix_nv[start] == n:
                    result.append(w[start:end])
                elif prefix_nv[end] - prefix_nv[start] > n:
                    break
    return result



