def search(lst):
    '''
    Given a list of positive integers, return the greatest integer x such that the frequency of x in the list is greater than or equal to x itself. 
    The frequency of an integer is the number of times it appears in the list.
    If no such integer exists, return -1.

    Examples:
        search([4, 1, 2, 2, 3, 1]) == 2
        search([1, 2, 2, 3, 3, 3, 4, 4, 4]) == 3
        search([5, 5, 4, 4, 4]) == -1
    '''
    from collections import Counter
    freq = Counter(lst)
    candidates = [x for x in freq if freq[x] >= x and x > 0]
    return max(candidates) if candidates else -1



