from typing import List

def mean_absolute_deviation(numbers: List[float]) -> float:
    """
    Calculate the Mean Absolute Deviation (MAD) of a list of numbers around their mean.

    The Mean Absolute Deviation is defined as the average of the absolute differences 
    between each number in the list and the mean of the list:

        MAD = average of |x - mean(numbers)|

    Parameters:
        numbers (List[float]): A non-empty list of floating-point numbers.

    Returns:
        float: The Mean Absolute Deviation of the input numbers around their mean.

    Raises:
        ValueError: If the input list is empty, since the mean and MAD are undefined.

    Examples:
        >>> mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
        1.0
    """
    if not numbers:
        raise ValueError("Input list is empty; mean and MAD are undefined.")
    mean = sum(numbers) / len(numbers)
    return sum(abs(x - mean) for x in numbers) / len(numbers)



