from typing import List

def parse_music(music_string: str) -> List[int]:
    """
    Parses a string representing musical notes in a special ASCII format and returns a list of integers
    corresponding to the number of beats each note lasts.

    Legend of note symbols and their beat durations:
      - 'o'  : whole note, lasts 4 beats
      - 'o|' : half note, lasts 2 beats
      - '.|' : quarter note, lasts 1 beat

    Notes are separated by spaces.

    Example:
    >>> parse_music('o o| .| o| o| .| .| .| .| o o')
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
    """
    beat_map = {'o':4, 'o|':2, '.|':1}
    if not music_string.strip():
        return []
    tokens = music_string.split()
    return [beat_map[token] for token in tokens]



