def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    # Check if arr is already sorted non-decreasingly
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True
    # Try all right shifts: each right shift moves last element to front
    for shift in range(1, n):
        # Effective rotation to left by (n - shift) is equivalent to right shift by shift
        rotated = arr[-shift:] + arr[:-shift]
        if all(rotated[i] <= rotated[i+1] for i in range(n-1)):
            return True
    return False



