def select_words(s, n):
    """Given a string s and a natural number n, return a list of all words from s that contain exactly n consonants, 
    in the order these words appear in s.
    If s is empty, return an empty list.
    You may assume s contains only letters and spaces.

    Examples:
    select_words("Mary had a little lamb", 4) ==> ["had"]
    select_words("Mary had a little lamb", 3) ==> ["lamb"]
    select_words("simple white space", 2) ==> ["white"]
    select_words("Hello world", 4) ==> ["Hello"]
    select_words("Uncle sam", 3) ==> ["sam"]
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    if not s:
        return []
    words = s.split()
    result = []
    for word in words:
        consonant_count = sum(1 for ch in word.lower() if ch.isalpha() and ch not in vowels)
        if consonant_count == n:
            result.append(word)
    return result



