def decode_shift(s: str) -> str:
    """
    Takes as input a string encoded by shifting every character forward by 5 positions in the alphabet (a–z),
    and returns the decoded lowercase string by shifting every character backward by 5 positions within 'a'-'z'.

    Each character in the input string `s` is expected to be a lowercase letter ('a'–'z').
    The decoding shifts letters backward by 5 with wrap-around (e.g., 'a' shifted backward by 5 becomes 'v').

    Example:
    decode_shift("mjqqt") -> "hello"
    decode_shift("ozruq") -> "jtolm"
    """
    shift = 5
    decoded_chars = []
    for c in s:
        val = ord(c) - shift
        if val < ord('a'):
            val += 26
        decoded_chars.append(chr(val))
    return ''.join(decoded_chars)



