def monotonic(l: list):
    """
    Return True if the list elements are monotonic, meaning the elements are either entirely
    non-decreasing (each element is greater than or equal to the previous) or entirely
    non-increasing (each element is less than or equal to the previous) throughout the list.
    Return False if the list changes direction at any point.

    Examples:
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if not l or len(l) == 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, len(l)):
        if l[i] < l[i - 1]:
            non_decreasing = False
        if l[i] > l[i - 1]:
            non_increasing = False
        if not non_decreasing and not non_increasing:
            return False
    return True



