def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    # We want to find nonnegative integers a, b such that n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a - b >= 0 and y = a + b >= x, so n = x*y
    # Both a and b are integers >=0 => (x + y) and (y - x) must be even and nonnegative
    # So x and y have the same parity (both even or both odd)
    # We try to find factors x,y of n with x <= y, x,y >=0, same parity, and then check if a,b are integers >=0.
    # For negative n, factors x,y can be negative, but since a,b >=0, x,y must be >=0.
    # So for negative n, x,y >=0 implies n=x*y >=0, contradiction unless n=0.
    # But from tests, negative n can be representable if (0^2 - b^2 = negative n), so x=0,y=abs(n)
    # So x can be zero.
    # So we search x in range [0, sqrt(|n|)+1] and check if n divisible by x
    # But x=0 is special: if x=0, then n=0*y=0, so n must be zero
    # So x>0
    # We'll iterate x from 1 to int(abs(n)**0.5)+1 if n!=0 else 0
    # For negative n, factor pairs with positive x,y can't produce negative n, so handle separately:
    # Actually, n = a^2 - b^2 = (a-b)(a+b)
    # If n<0, then (a-b)(a+b)<0 => one factor positive, one negative, impossible if a,b >=0 (since a+b >= a-b)
    # So negative n is representable only if a=0 and b>0 => n=0 - b^2 negative perfect square
    # So check if n is negative perfect square (i.e. -k^2)
    if n < 0:
        # Check if -n is a perfect square
        k = int((-n) ** 0.5)
        return k * k == -n

    limit = int(n**0.5) + 1
    for x in range(0, limit):
        if x == 0:
            # If x=0, n=0*y=0, so n must be zero
            if n == 0:
                return True
            else:
                continue
        if n % x != 0:
            continue
        y = n // x
        if y < x:
            continue
        # Check parity
        if (x % 2) != (y % 2):
            continue
        a = (x + y) // 2
        b = (y - x) // 2
        if a >= 0 and b >= 0:
            return True
    return False



