def zip_tuples(*tuples):
    from itertools import cycle
    if not tuples:
        return ()
    first = tuples[0]
    if len(tuples) == 1:
        return tuple((x,) for x in first)
    result = []
    for i in range(len(first)):
        zipped = [first[i]]
        for t in tuples[1:]:
            if not t:
                # cycling empty tuple is undefined, will raise IndexError on access
                raise IndexError("Cannot cycle an empty tuple")
            zipped.append(t[i % len(t)])
        result.append(tuple(zipped))
    return tuple(result)



