def find_solution(a: int, b: int, n: int):
    # Handle the case when both a and b are zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else 'No solution'

    # Handle the case when a == 0
    if a == 0:
        if b == 0:
            return (0, 0) if n == 0 else 'No solution'
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return 'No solution'

    # Handle the case when b == 0
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return 'No solution'

    # General case: a != 0 and b != 0
    # We want to find minimal x >= 0 such that y = (n - a*x)/b is integer and y >= 0.

    # Because a and b might be negative, and no guaranteed monotonic behavior for n - a*x,
    # we cannot rely on monotonic break conditions.
    # So we try all x >= 0 until no solution found or until some stopping condition.

    # Since problem does not limit search bounds, but to avoid infinite loops,
    # we consider that if for some x the value (n - a*x) moves away indefinitely from divisibility or positivity,
    # we can stop. But since a and b can be negative, no monotonicity is guaranteed.
    # So we will try a more robust approach:

    # We will try all x >= 0 such that y = (n - a*x)/b >= 0 and integer.
    # To avoid infinite loop, we consider that if for increasing x, abs(n - a*x) grows beyond abs(n) + abs(a)*100000, stop.

    # But since spec has no bounds, we must find a strategy:

    # Let's try to compute the set of x >= 0 for which y >= 0:
    # y = (n - a*x)/b >= 0
    # => (n - a*x) and b have the same sign or n - a*x == 0

    # We'll try x = 0 up to a large number (e.g. 10**6) and check solutions.

    # But to handle very large inputs efficiently, we can do the following:

    # Since x, y >= 0 and a,b,n integers, rewrite:
    # a*x + b*y = n
    # y = (n - a*x)/b

    # For y to be integer and >= 0:
    # (n - a*x) % b == 0 and (n - a*x)/b >= 0

    # We'll try x from 0 upwards until no solutions can appear:
    # Since a and b can be negative, no simple monotonic stopping condition.
    # But since minimal x solution is required, we can try a brute force search,
    # but to avoid infinite loop, we limit to 10**6 tries (arbitrary large).

    LIMIT = 10**6

    for x in range(LIMIT + 1):
        numerator = n - a * x
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)

    return 'No solution'



