def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m if m >= 1 else 0
    if m < 1 or n < 1:
        return 0

    # dp[i][x]: number of sequences of length i ending with element x
    # Use only two rows to save memory
    prev_dp = [1] * (m + 1)  # For length 1, sequences ending at x are 1 for all x in [1..m]
    curr_dp = [0] * (m + 1)

    for length in range(2, n + 1):
        # Compute prefix sums for prev_dp to allow fast sum queries
        prefix_sum = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix_sum[x + 1] = prefix_sum[x] + prev_dp[x]

        for x in range(1, m + 1):
            lower_bound = 2 * x
            if lower_bound > m:
                curr_dp[x] = 0
            else:
                # sum of prev_dp[y] for y in [lower_bound .. m]
                curr_dp[x] = prefix_sum[m + 1] - prefix_sum[lower_bound]

        prev_dp, curr_dp = curr_dp, [0] * (m + 1)

    total = sum(prev_dp[1:])
    return total if total > 0 else 0



