def remove_column(matrix: list[list], col_index: int) -> list[list]:
    # First check that every row has an element at col_index
    for row in matrix:
        # Validate index in range for each row
        if not (-len(row) <= col_index < len(row)):
            raise IndexError("Column index out of range for a row")
    # Build new matrix with the specified column removed from each row
    result = []
    for row in matrix:
