def permute_string(s: str) -> None:
    chars = sorted(s)
    n = len(chars)
    used = [False] * n
    path = []

    def backtrack():
        if len(path) == n:
            print(''.join(path))
            return
        prev_char = None
        for i in range(n):
            if used[i]:
                continue
            if chars[i] == prev_char:
                continue
            used[i] = True
            path.append(chars[i])
            backtrack()
            path.pop()
            used[i] = False
            prev_char = chars[i]

    backtrack()



