def filter_data(student_data, max_height, max_width):
    try:
        # Attempt to reconstruct result with same type as input
        result = type(student_data)(s for s in student_data if getattr(s, 'height', float('-inf')) >= max_height and getattr(s, 'width', float('-inf')) >= max_width)
    except TypeError:
        # If type constructor does not accept generator (e.g. set), fallback to list and convert if possible
        filtered = [s for s in student_data if getattr(s, 'height', float('-inf')) >= max_height and getattr(s, 'width', float('-inf')) >= max_width]
        try:
            result = type(student_data)(filtered)
        except Exception:
            result = filtered
    return result



