def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    # Compute last digit of product (a+1)*(a+2)*...*b
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
        if last_digit == 0:
            # Once last digit is zero, it remains zero
            break
    return last_digit



