from typing import Optional

def next_smallest_palindrome(number: int) -> Optional[int]:
    if number <= 1:
        return None
    s = str(number)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # Helper to create palindrome from left half
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    # If number is very small, handle directly
    if number <= 10:
        # Palindromes less than number are digits < number - 1
        return number - 1 if number > 0 else None

    # Try to find palindrome smaller than number by manipulating left half
    half_len = (length + 1) // 2
    left = s[:half_len]
    odd_length = (length % 2 != 0)

    # Start with palindrome formed by left half
    pal = make_palindrome(left, odd_length)
    if pal >= number:
        # Need to decrement the left half and try again
        left_num = int(left)
        left_num -= 1
        if left_num == 0:
            # This means palindrome smaller with fewer digits
            # e.g., from 1000, try 999
            smaller = int('9' * (length - 1))
            return smaller if smaller < number else None
        left_str = str(left_num)
        # Pad left_str with zeros if needed
        left_str = left_str.zfill(len(left))
        pal = make_palindrome(left_str, odd_length)
        if pal < number:
            return pal
        else:
            # If still not smaller, try smaller length palindrome
            smaller = int('9' * (length - 1))
            return smaller if smaller < number else None
    else:
        # pal < number
        return pal

    # Fallback: no smaller palindrome found
    return None



