def reverse_Array_Upto_K(sequence, K):
    if K <= 0:
        return sequence
    n = len(sequence)
    k = min(K, n)
    first_part = sequence[:k][::-1]
    rest_part = sequence[k:]
    if isinstance(sequence, str):
