def odd_length_sum(arr: list[int]) -> int:
    n = len(arr)
    if n == 0:
        return 0
    max_odd_length = n if n % 2 == 1 else n - 1
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + arr[i]
    total = 0
    for length in range(1, max_odd_length + 1, 2):
        for start in range(n - length + 1):
            total += prefix[start + length] - prefix[start]
    return total



