from collections.abc import Iterable

def substract_elements(a, b):
    # Check for unordered collections (sets) anywhere
    def check_ordered(x):
        if isinstance(x, set):
            raise TypeError("Unordered collection (set) encountered")
        if isinstance(x, Iterable) and not isinstance(x, (str, bytes)):
            # For iterables, check all elements recursively
            for e in x:
                check_ordered(e)

    check_ordered(a)
    check_ordered(b)

    # Recursive function for subtraction with shape and type checks
    def recurse(x, y):
        # Both must be iterables (except str/bytes)
        is_x_iter = isinstance(x, Iterable) and not isinstance(x, (str, bytes))
        is_y_iter = isinstance(y, Iterable) and not isinstance(y, (str, bytes))
        if is_x_iter != is_y_iter:
            raise ValueError("Shape mismatch: one is iterable, other is not")
        if not is_x_iter and not is_y_iter:
            # Both are scalars: subtract
            return x - y
        # Both are iterables: check length and recurse elementwise
        len_x = len(x) if hasattr(x, '__len__') else None
        len_y = len(y) if hasattr(y, '__len__') else None
        if len_x is None or len_y is None or len_x != len_y:
            raise ValueError("Shape mismatch: differing lengths")
        result_elems = [recurse(xi, yi) for xi, yi in zip(x, y)]
        # Preserve type of x
        if isinstance(x, tuple):
            return tuple(result_elems)
        elif isinstance(x, list):
            return list(result_elems)
        else:
            # For other ordered iterables, try to reconstruct
            try:
                return type(x)(result_elems)
            except Exception:
                # If cannot reconstruct, fallback to list
                return list(result_elems)

    return recurse(a, b)



