def dif_Square(n: int) -> bool:
    """
    Determine whether the given integer n can be expressed as the difference of two integer squares, 
    i.e., whether there exist integers a and b such that n = a² - b².

    The function accepts all integers n (positive, negative, or zero) as input and returns True if 
    such integers a and b exist, and False otherwise.

    Examples:
    - dif_Square(0)  -> True   # 0 = 0² - 0²
    - dif_Square(15) -> True   # 15 = 4² - 1²
    - dif_Square(-15) -> True  # -15 = 4² - 7²
    - dif_Square(1)  -> True   # 1 = 1² - 0²
    - dif_Square(2)  -> False  # 2 cannot be expressed as difference of two squares
    """
    # A number can be expressed as a difference of two squares if and only if it is NOT congruent to 2 modulo 4.
    # This holds for all integers n (including negative and zero).
    return n % 4 != 2



