def find_solution(a, b, n):
    if n < 0:
        return None
    # Handle cases when a or b is zero
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        return None
    if b == 0:
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None
    # Ensure a and b are positive for iteration range
    a_abs, b_abs = abs(a), abs(b)
    max_y = n // b_abs if b_abs != 0 else 0
    for y in range(max_y + 1):
        rem = n - b * y
        if rem < 0:
            break
        if a != 0 and rem % a == 0:
            x = rem // a
            if x >= 0 and y >= 0:
                return (x, y)
    return None



