def flatten_list(nested_list):
    """
    Recursively flattens a nested list of arbitrary depth into a single-level list containing all elements,
    while leaving the input nested list unchanged.

    Parameters:
    nested_list (list): A list which may contain other nested lists to any depth.

    Returns:
    list: A new flattened list containing all elements from the nested lists, preserving non-list iterables
    (such as tuples, sets, or strings) as single elements without flattening them.
    """
