def find_Max(array, start, end):
    # Since the array segment is sorted and rotated, the maximum element is the pivot point.
    # We can find it using a modified binary search in O(log n).
    while start < end:
        mid = (start + end) // 2
        if array[mid] > array[end]:
            start = mid + 1
        else:
            end = mid
    # After loop, start points to the minimum element,
    # so the maximum is the element before start, considering wrap-around.
    max_index = start - 1 if start > 0 else len(array) - 1
    # If the segment is smaller than the whole array, adjust max_index to be within [start_input,end_input]
    # Because the segment might not be the entire array, max_index must be inside the segment.
    # So check if max_index < original start, if so, max is at end.
    # Also consider if start == end (single element)
    segment_start, segment_end = start, end
    # Since start and end are local variables here, save original parameters:
    # Actually, to avoid confusion, better rename input parameters:
    # Let's use original input parameters to check bounds:
    orig_start, orig_end = start, end
    # But start and end have changed. Let's fix by capturing original inputs before loop:
def find_Max(array, start, end):
    orig_start, orig_end = start, end
    while start < end:
        mid = (start + end) // 2
        if array[mid] > array[end]:
