def lucky_num(n: int) -> list[int]:
    nums = list(range(1, n * 10))  # Start with a range large enough to get n lucky numbers
    idx = 1
    while len(nums) >= idx:
        step = nums[idx]
        if step > len(nums):
            break
        # Remove every step-th element starting from index step-1
        del nums[step - 1::step]
        idx += 1
        if len(nums) >= n and idx > n * 2:
            # Safety break if too large, though usually not needed
            break
    return nums[:n]



