def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        # Next palindrome after all 9's is 10..01 with length+1 digits
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd: bool) -> int:
        if odd:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = length // 2
    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd)
    if palindrome > n:
        return palindrome

    # Increment the middle part (left)
    left_num = int(left)
    left_num += 1
    left_inc = str(left_num)
    # Handle length change after increment (e.g., 99 + 1 = 100)
    if len(left_inc) > len(left):
        # This happens when incrementing causes length increase
        # e.g. 999 -> left part 999 + 1 = 1000, so palindrome length increases by 1 or 2
        if odd:
            # For odd length, new palindrome will be of length+1
            return int('1' + ('0' * (length - 1)) + '1')
        else:
            # For even length, new palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
    else:
        return make_palindrome(left_inc, odd)



