def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of sequences of length i+1 ending with element x
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # sequences of length 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        # prefix sums for dp to optimize counting
        # But here, each dp[x] depends on dp[y] where y is previous element s.t. x >= 2*y
        # So for each x, sum dp[y] for y in [ceil(x/2), ...]
        # Actually, for each previous y, next x >= 2*y, so for each y, next elements x in [2*y, m]
        # So to optimize, for each y, add dp[y] to all new_dp[x] with x >= 2*y
        # We'll do the inverse: for each y, add dp[y] to new_dp[x] for x in [2*y, m]
        # To avoid O(m^2), we do difference array approach
        diff = [0] * (m + 2)
        for prev in range(1, m + 1):
            start = 2 * prev
            if start <= m:
                diff[start] += dp[prev]
                diff[m + 1] -= dp[prev]
        # accumulate diff
        acc = 0
        for x in range(1, m + 1):
            acc += diff[x]
            new_dp[x] = acc
        dp = new_dp
    return sum(dp[1:])



