def remove_column(nested_list, col_idx):
    result = []
    for row in nested_list:
        length = len(row)
        # Normalize negative index
        if col_idx < 0:
            idx = col_idx + length
        else:
            idx = col_idx
        if 0 <= idx < length:
            # Remove the element at idx
            new_row = row[:idx] + row[idx+1:]
            result.append(new_row)
        else:
            # Keep original row object unchanged
            result.append(row)
    return result



