import re

def capital_words_spaces(s: str) -> str:
    # If input contains spaces, split into tokens and process each separately to preserve spacing
    if ' ' in s:
        tokens = s.split(' ')
        return ' '.join(capital_words_spaces(token) for token in tokens)

    # Pattern to match words:
    # - Acronyms: 2+ uppercase letters (e.g. NASA, USA)
    # - Capitalized words: uppercase followed by lowercase letters (e.g. Hello, World)
    # - Lowercase words: all lowercase letters (e.g. and, enjoy)
    # Using a pattern with alternation and lookahead to find all words in order
    pattern = re.compile(r'''
        ([A-Z]{2,})           # Acronym: 2+ uppercase letters
        |([A-Z][a-z]+)        # Capitalized word: uppercase + lowercase letters
        |([a-z]+)             # Lowercase word: sequence of lowercase letters
    ''', re.VERBOSE)

    matches = pattern.findall(s)
    if not matches:
        return s  # no matches found, return original string

    # Extract matched groups: each match is a tuple of 3 groups, only one non-empty per match
    words = [m[0] or m[1] or m[2] for m in matches]

    # Join with spaces to separate concatenated words
    return ' '.join(words)



