def lucky_num(n: int) -> list[int]:
    # Start with natural numbers beginning with 1
    numbers = list(range(1, 2 * n * 10))  # Start with a sufficiently large list
    idx = 1  # Index of the current lucky number (starting from second element, since first is 1)
    while idx < len(numbers) and len(numbers) < n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number in the list (1-based indexing)
        # Positions to remove are multiples of step: step, 2*step, 3*step, ...
        # Because list is zero-based, these correspond to indices step-1, 2*step-1, ...
        numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
        idx += 1
        if len(numbers) >= n:
            break
    # If after first sieve the list is still too small (rare), extend and continue
    while len(numbers) < n:
        # Extend the list by adding more numbers
        last = numbers[-1]
        extension = list(range(last + 1, last + 1000))
        numbers.extend(extension)
        # Continue sieving from current idx
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            numbers = [num for i, num in enumerate(numbers, start=1) if i % step != 0]
            idx += 1
            if len(numbers) >= n:
                break
    return numbers[:n]



