def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 1:
        return m
    if m == 1:
        return 0 if n > 1 else 1

    from functools import lru_cache

    @lru_cache(None)
    def dp(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        start = max(prev * 2, prev)  # a_i >= 2 * a_{i-1} and nondecreasing means a_i >= 2*prev
        for cur in range(start, m + 1):
            total += dp(pos + 1, cur)
        return total

    total_sequences = 0
    for first in range(1, m + 1):
        total_sequences += dp(1, first)
    return total_sequences



