def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        else:
            g, s, t = extended_gcd(y, x % y)
            return (g, t, s - (x // y) * t)

    if a == 0 and b == 0:
        if n == 0:
            return (0, 0)  # Infinite solutions, return one valid solution
        else:
            return "No solution"

    g, x0, y0 = extended_gcd(abs(a), abs(b))
    if n % g != 0:
        return "No solution"

    x0 *= n // g
    y0 *= n // g

    if a < 0:
        x0 = -x0
    if b < 0:
        y0 = -y0

    return (x0, y0)



