def find_exponentio(bases, exponents):
    if not (isinstance(bases, tuple) and isinstance(exponents, tuple)):
        raise TypeError("Both inputs must be tuples.")
    if len(bases) != len(exponents):
        raise ValueError("Input tuples must be of the same length.")
    result = []
    for b, e in zip(bases, exponents):
        # Check numeric type
        if not (hasattr(b, "__pow__") and hasattr(e, "__pow__")) and not (isinstance(b, (int, float, complex)) and isinstance(e, (int, float, complex))):
            raise TypeError("Both base and exponent must be numeric types.")
        # Check for negative base with fractional exponent to avoid complex results
        if isinstance(b, (int, float)) and b < 0:
            # If exponent is float and not integer-valued, raise error
            if isinstance(e, float):
                if not e.is_integer():
                    raise ValueError("Negative base with fractional exponent results in complex number.")
            elif isinstance(e, complex):
                raise ValueError("Negative base with complex exponent results in complex number.")
            # For other numeric types (e.g. int), no problem
        try:
            val = b ** e
        except Exception as ex:
            # Propagate exceptions for invalid operations
            raise ex
        # If result is complex but base and exponent were real, raise error (to disallow implicit complex)
        if isinstance(val, complex):
            # Check if base and exponent are real numbers
            if all(isinstance(x, (int, float)) for x in (b, e)):
                raise ValueError("Result is complex, which is disallowed for real base and exponent.")
        result.append(val)
    return tuple(result)



