def text_match_two_three(string: str) -> str:
    """
    Check if the input string contains the pattern of an 'a' character followed immediately by 
    either two or three consecutive 'b' characters.

    The function returns a string indicating whether such a pattern exists.

    Specifically, it looks for the substring "abb" or "abbb" anywhere within the input string.

    Parameters:
    - string (str): The input string to search within.

    Returns:
    - str: "Match found" if the pattern "abb" or "abbb" is present in the string; otherwise, "No match".
    """
    if "abb" in string or "abbb" in string:
        # We must ensure that if "abb" is matched, it is not part of a longer sequence like "abbbb".
        # So we check that "abb" is not followed by an additional 'b'
        # For "abbb", no further 'b's should follow to avoid matching "abbbb"
        # But since "abbb" contains "abb", the above condition may be ambiguous.
        # To be exact: we need to find an occurrence of "abb" or "abbb" which is not part of "abbbb" or longer.
        # So we scan string to find any "abb" or "abbb" occurrence with no extra 'b' immediately after.

        # Check occurrences of "abb" not followed by 'b'
        idx = 0
        while True:
            idx = string.find("abb", idx)
            if idx == -1:
                break
            # Check if next char after "abb" is not 'b'
            if idx + 3 >= len(string) or string[idx + 3] != 'b':
                return "Match found"
            idx += 1

        # Check occurrences of "abbb" not followed by 'b'
        idx = 0
        while True:
            idx = string.find("abbb", idx)
            if idx == -1:
                break
            # Check if next char after "abbb" is not 'b'
            if idx + 4 >= len(string) or string[idx + 4] != 'b':
                return "Match found"
            idx += 1

    return "No match"



