from collections import Counter

def permute_string(s):
    if s == "":
        return []
    counts = Counter(s)
    length = len(s)
    result = []
    path = []

    def backtrack():
        if len(path) == length:
            result.append("".join(path))
            return
        for ch in counts:
            if counts[ch] > 0:
                counts[ch] -= 1
                path.append(ch)
                backtrack()
                path.pop()
                counts[ch] += 1

    backtrack()
    return result



