def text_match(text: str) -> bool:
    """
    Determine whether the given input text matches the internally defined pattern.

    The pattern requires that the input text:
    - Starts with the character 'a'
    - Ends with either the character 'a' or 'c'
    - May contain any characters (including none) in between

    Parameters:
    text (str): The input string to be checked against the pattern.

    Returns:
    bool: True if the input text matches the pattern; False otherwise.

    Examples:
    >>> text_match("a")
    True
    >>> text_match("abc")
    True
    >>> text_match("ab")
    False
    >>> text_match("ac")
    True
    >>> text_match("ba")
    False
    """
    if len(text) == 0:
        return False
    return text[0] == 'a' and (text[-1] == 'a' or text[-1] == 'c')



