def capital_words_spaces(text: str, prefix: str) -> str:
    result = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if (
            c.isupper() and
            i > 0 and
            (text[i-1].isalnum() or text[i-1] == '_') and
            text[i:i+len(prefix)] == prefix
        ):
            if i == 0 or text[i-1] != ' ':
                # Insert space before c
                result.append(' ')
        result.append(c)
        i += 1
    return ''.join(result)



