def get_total_number_of_sequences(n: int, m: int) -> int:
    if n == 1:
        return m
    # dp[i][x]: number of sequences of length i+1 starting with element x
    # where i ranges from 0 to n-1, x ranges from 1 to m inclusive
    dp = [0] * (m + 1)
    for x in range(1, m + 1):
        dp[x] = 1  # sequences of length 1

    for length in range(1, n):
        new_dp = [0] * (m + 1)
        # Use prefix sums to speed up summation over ranges
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[x]
        for x in range(1, m + 1):
            low = 2 * x
            if low <= m:
                new_dp[x] = prefix[m] - prefix[low - 1]
            else:
                new_dp[x] = 0
        dp = new_dp
    return sum(dp[1 : m + 1])



