def substract_elements(minuend, subtrahend):
    import numbers

    if not isinstance(minuend, tuple) or not isinstance(subtrahend, tuple):
        raise TypeError("Both arguments must be tuples")

    if len(minuend) != len(subtrahend):
        raise ValueError("Tuples differ in length")

    result = []
    for a, b in zip(minuend, subtrahend):
        if isinstance(a, tuple) and isinstance(b, tuple):
            # recurse
            res = substract_elements(a, b)
            result.append(res)
        elif isinstance(a, tuple) or isinstance(b, tuple):
            raise ValueError("Tuples differ in structure")
        else:
            # Check numeric
            if not isinstance(a, numbers.Number) or not isinstance(b, numbers.Number):
                raise TypeError("Non-numeric element encountered")
            result.append(a - b)
    return tuple(result)



