def lucky_num(n: int) -> list[int]:
    if n == 0:
        return []
    # Start with the list of odd numbers starting at 1
    # We generate a sufficiently large initial list to apply the sieve.
    # Since lucky numbers are sparse, we over-allocate and then sieve down.
    # If n is small, 50*n is enough, else scale up.
    limit = max(50 * n, 100)
    numbers = list(range(1, 2 * limit, 2))  # odd numbers starting from 1

    idx = 1  # start removing using the second number as step (index 1)
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list
        # The counting is 1-based on the current list, so remove numbers at indices step-1, 2*step-1, ...
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n and idx >= n:
            # We have enough lucky numbers
            break
    return numbers[:n]



